        }
        Install-ADDSForest @installADDSParams;
        Write-Verbose -Message ($localizedData.CreatedForest -f $DomainName); 
    }  

    "Finished" | Out-File -FilePath (Get-TrackingFilename -DomainName $DomainName) -Force

